/**
 * The "Enter task title" row at the end of each group (groupAddRow). Enter emits `create-task` and the
 * field keeps the focus for the next title, even though the table redraws when the new task arrives.
 */
import { defineComponent, h, onBeforeUnmount, onMounted, ref } from "vue";
import type { TreeTableContext } from "./context";
import type { TreeTableId } from "./types";

export function useAddRow(ctx: TreeTableContext) {
    /* Kept here, not in the row, because the row is drawn again when the new task arrives:
       which group's field has the focus, and what is typed in each */
    const addFocus = ref<TreeTableId | null>(null);
    const addDrafts = new Map<TreeTableId, string>();

    const AddTaskInput = defineComponent({
        props: {
            groupId: { type: [String, Number], required: true },
            placeholder: { type: String, default: "" },
        },
        setup(p) {
            const input = ref<HTMLInputElement | null>(null);
            /* Restore what was typed; the focus comes back once Tabulator has put the row on the page */
            onMounted(() => {
                if (input.value) input.value.value = addDrafts.get(p.groupId) ?? "";
            });
            function submit() {
                const title = (input.value?.value ?? "").trim();
                if (!title) return;
                addDrafts.delete(p.groupId);
                if (input.value) input.value.value = "";
                addFocus.value = p.groupId;
                ctx.emit("create-task", { groupId: p.groupId, title });
            }
            function onKeydown(e: KeyboardEvent) {
                e.stopPropagation();
                if (e.key === "Enter") {
                    e.preventDefault();
                    submit();
                } else if (e.key === "Escape") {
                    e.preventDefault();
                    addDrafts.delete(p.groupId);
                    if (input.value) input.value.value = "";
                    addFocus.value = null;
                    input.value?.blur();
                }
            }
            return () =>
                h("span", { class: "fu-treetable__add-row" }, [
                    h("span", { class: "fu-treetable__add-row-mark", "aria-hidden": "true" }),
                    h("input", {
                        ref: input,
                        class: "fu-treetable__add-row-input",
                        "data-group-id": String(p.groupId),
                        type: "text",
                        placeholder: p.placeholder,
                        "aria-label": p.placeholder || "New task title",
                        onInput: (e: Event) => addDrafts.set(p.groupId, (e.target as HTMLInputElement).value),
                        onFocus: () => (addFocus.value = p.groupId),
                        onKeydown,
                    }),
                ]);
        },
    });

    /**
     * Puts the cursor back in the group's title field after the table redraws (Tabulator may re-attach rows
     * more than once). With `reveal`, scrolls just enough to keep the field in view, so a new task at the
     * bottom pushes the page up instead of hiding the field.
     */
    function focusAddRow(reveal = false) {
        if (addFocus.value === null || !ctx.host.value) return;
        const id = String(addFocus.value);
        const field = [...ctx.host.value.querySelectorAll<HTMLInputElement>(".fu-treetable__add-row-input")].find(
            (el) => el.dataset.groupId === id,
        );
        if (!field) return;
        if (document.activeElement !== field) field.focus({ preventScroll: true });
        if (reveal) field.closest(".tabulator-row")?.scrollIntoView({ block: "nearest" });
    }

    /* The field loses focus while the table redraws, so blur can't tell us the person left. Only a click
       elsewhere, focus moving to something else, or Escape does. */
    function onLeave(e: Event) {
        if (addFocus.value === null) return;
        if ((e.target as HTMLElement | null)?.closest?.(".fu-treetable__add-row-input")) return;
        addFocus.value = null;
    }
    onMounted(() => {
        document.addEventListener("pointerdown", onLeave, true);
        document.addEventListener("focusin", onLeave, true);
    });
    onBeforeUnmount(() => {
        document.removeEventListener("pointerdown", onLeave, true);
        document.removeEventListener("focusin", onLeave, true);
    });

    /** Draws the field into the title row's cell, and gives it the focus back after a redraw. */
    function renderAddCell(wrap: HTMLElement, groupId: TreeTableId, onRendered: (fn: () => void) => void) {
        ctx.mountVue(wrap, h(AddTaskInput, { groupId, placeholder: ctx.props.groupAddRowPlaceholder }));
        onRendered(() => {
            if (addFocus.value === groupId) wrap.querySelector<HTMLInputElement>("input")?.focus({ preventScroll: true });
        });
    }

    return { focusAddRow, renderAddCell };
}
