/**
 * The clickable colour square in a group header (groupColorEditable). Keeps its own colour while the
 * picker is open, so the square follows the picker live, and reports the colour once, when the picker closes.
 */
import { defineComponent, h, ref } from "vue";
import FuColorPopover from "../../colourPallet/FuColorPopover.vue";

export default defineComponent({
    name: "GroupColorSquare",
    props: {
        color: { type: String, default: "" },
        swatches: { type: Array as () => string[], default: () => [] },
        label: { type: String, default: "" },
    },
    emits: ["change"],
    setup(p, { emit }) {
        const current = ref(p.color);
        return () =>
            h(
                FuColorPopover,
                {
                    modelValue: current.value || "#9ca3af",
                    "onUpdate:modelValue": (v: string) => (current.value = v),
                    onClose: () => {
                        if (current.value && current.value !== p.color) emit("change", current.value);
                    },
                    swatches: p.swatches,
                    bare: true,
                    size: "xs",
                },
                {
                    trigger: () =>
                        h("span", {
                            class: ["fu-treetable__group-color", "is-editable", { "is-empty": !current.value }],
                            style: current.value ? { background: current.value } : undefined,
                            title: `Change colour of ${p.label}`,
                            "aria-label": `Change colour of ${p.label}`,
                        }),
                },
            );
    },
});
