<template>
  <label
    class="fu-checkbox"
    :class="[`fu-checkbox--${size}`, { 'fu-checkbox--disabled': disabled }]"
    :for="id"
  >
    <input
      type="checkbox"
      class="fu-checkbox__input"
      :id="id"
      :checked="modelValue"
      :disabled="disabled"
      :aria-required="required || undefined"
      @change="$emit('update:modelValue', ($event.target as HTMLInputElement).checked)"
    />
    <span class="fu-checkbox__box"></span>
    <span v-if="label" class="fu-checkbox__label"
      >{{ label }}<span v-if="required" class="fu-input-required" aria-hidden="true">*</span></span
    >
  </label>
</template>

<script setup lang="ts">
const props = withDefaults(
  defineProps<{
    modelValue?: boolean;
    label?: string;
    id?: string;
    size?: "sm" | "md";
    disabled?: boolean;
    /** Shows a red * after the label and sets aria-required. Visual only: no validation. */
    required?: boolean;
  }>(),
  {
    size: "md",
    modelValue: false,
    required: false,
  }
);

defineEmits<{
  (e: "update:modelValue", value: boolean): void;
}>();
</script>

<style lang="scss" scoped>
@use "./FuCheckbox.scss";

/* Same as FusionTextInput's required star */
.fu-input-required {
  color: var(--fu-color-danger);
  margin-left: rem-calc(2);
}
</style>
