<script setup lang="ts">
/**
 * FusionTreeTable
 * A collapsible tree table built on Tabulator, styled to match FusionListView.
 * Controlled: the parent owns data, selection and column order.
 *
 * This file holds the API (props in ./types.ts, emits here), the Tabulator setup and the template.
 * Each part lives in its own file next to it and shares one context (./context.ts):
 *   data.ts            rows handed to Tabulator, the rows added to groups, the sorter
 *   cells.ts           columns and the cell formatter (cell slots)
 *   useGroupHeader.ts  group headers; useGroupDetails.ts the details card; parts/GroupColorSquare.ts
 *   useAddRow.ts       the "Enter task title" row; useMoreRow.ts the "Show more" row
 *   useRows.ts         row state, drag and drop; useSelection.ts; useSort.ts; useColumnDrag.ts
 *   useSync.ts         applying the parent's changes (rows, groups, columns) to Tabulator
 *   tree.ts, guides.ts, scroll.ts, skeleton.ts  small helpers
 */
import { computed, getCurrentInstance, nextTick, onBeforeUnmount, onMounted, ref, useSlots, watch } from "vue";
import {
    Tabulator,
    DataTreeModule,
    FormatModule,
    FrozenColumnsModule,
    GroupRowsModule,
    InteractionModule,
    MoveColumnsModule,
    ResizeColumnsModule,
    ResizeTableModule,
    SelectRowModule,
    SortModule,
    type GroupComponent,
    type RowComponent,
} from "tabulator-tables";
import "tabulator-tables/dist/css/tabulator.min.css";
import "./TreeTable.scss";
import { createMountVue, type TreeTableContext, type TreeTableState } from "./context";
import type { TreeTableId, TreeTableProps, TreeTableResolvedProps, TreeTableSort } from "./types";
import type { TreeTableMove } from "./treeTableUtils";
import { isPhantom, tableData } from "./data";
import { refreshGuides } from "./guides";
import { skeletonWidth } from "./skeleton";
import { walk } from "./tree";
import { chevron, useCells } from "./cells";
import { useAddRow } from "./useAddRow";
import { useMoreRow } from "./useMoreRow";
import { useGroupDetails } from "./useGroupDetails";
import { useGroupHeader } from "./useGroupHeader";
import { useRows } from "./useRows";
import { useSelection } from "./useSelection";
import { useSort } from "./useSort";
import { useColumnDrag } from "./useColumnDrag";
import { useSync } from "./useSync";
export type {
    TreeTableColumn,
    TreeTableId,
    TreeTableGroupAction,
    TreeTableGroup,
    TreeTableGroupStyle,
    TreeTableSort,
    TreeTableProps,
} from "./types";
export type { TreeTableDropPosition, TreeTableMove } from "./treeTableUtils";

Tabulator.registerModule([
    DataTreeModule,
    FormatModule,
    FrozenColumnsModule,
    GroupRowsModule,
    InteractionModule,
    MoveColumnsModule,
    ResizeColumnsModule,
    ResizeTableModule,
    SelectRowModule,
    SortModule,
]);

const props = withDefaults(defineProps<TreeTableProps>(), 
    {
        idField: "id",
        childrenField: "children",
        stickyHeader: false,
        stickyOffset: 0,
        pinTreeColumn: true,
        groupStartOpen: true,
        groupAdd: false,
        groupAddLabel: "Add task",
        groupAddRow: false,
        groupAddRowPlaceholder: "Enter task title…",
        groupMoreLabel: "Show {n} more",
        groupMoreSize: 25,
        groupAvatarShape: "circle",
        groupDetailsWidth: "320px",
        groupDetailsAlign: "left",
        sortMode: "local",
        sort: undefined,
        groupStyle: "plain",
        groupColorEditable: false,
        showRowColor: true,
        selectable: true,
        selectedIds: () => [],
        propagateSelection: true,
        startExpanded: true,
        movableColumns: true,
        resizableColumns: true,
        sortable: true,
        draggableRows: true,
        indent: 22,
        loading: false,
        skeletonRows: 8,
        emptyText: "Nothing to show",
    },
);

const emit = defineEmits<{
    (e: "update:selectedIds", keys: TreeTableId[]): void;
    (e: "row-click", row: Record<string, any>): void;
    (e: "columns-reordered", keys: string[]): void;
    (e: "column-resized", payload: { key: string; width: number }): void;
    (e: "sort-change", sort: TreeTableSort | null): void;
    (e: "row-move", move: TreeTableMove): void;
    (e: "group-action", payload: { groupId: TreeTableId; action: string }): void;
    (e: "add-task", payload: { groupId: TreeTableId }): void;
    /** A title was typed in a group's last row (groupAddRow) and Enter pressed. Create the task and add it to `rows`. */
    (e: "create-task", payload: { groupId: TreeTableId; title: string }): void;
    /** A group's colour was picked (once, when the picker closes). Save it and pass the new colour back in `groups`. */
    (e: "group-color-change", payload: { groupId: TreeTableId; color: string }): void;
    /** The "Show more" row was clicked (or Enter pressed on it). Load the group's next rows, then update `rows` and the group's `more`. */
    (e: "group-load-more", payload: { groupId: TreeTableId }): void;
    /** A group was opened or closed by the person. Fetch a lazy group's rows when it opens. */
    (e: "group-toggle", payload: { groupId: TreeTableId; open: boolean }): void;
    /** The group details card (`#group-details`) opened or closed. */
    (e: "group-details-open", payload: { groupId: TreeTableId }): void;
    (e: "group-details-close", payload: { groupId: TreeTableId }): void;
    (e: "row-expanded", row: Record<string, any>): void;
    (e: "row-collapsed", row: Record<string, any>): void;
}>();

/* ---------- Shared context ---------- */

const slots = useSlots();
const instance = getCurrentInstance();
const host = ref<HTMLElement | null>(null);
const mounted = new Set<HTMLElement>();
const state: TreeTableState = { table: null, built: false, holderEl: null, syncingSelection: false };

const visibleColumns = computed(() => props.columns.filter((c) => c.visible !== false));
/* The tree column is fixed when the table is created, so dragging columns around never moves the tree to another column. */
const initialTreeKey = props.treeColumn ?? props.columns.find((c) => c.visible !== false)?.key;
const treeKey = computed(() => {
    const wanted = props.treeColumn ?? initialTreeKey;
    return visibleColumns.value.some((c) => c.key === wanted) ? wanted : visibleColumns.value[0]?.key;
});

const ctx: TreeTableContext = {
    props: props as TreeTableResolvedProps,
    emit,
    slots,
    appContext: instance?.appContext ?? null,
    host,
    state,
    mounted,
    visibleColumns,
    treeKey,
    idOf: (row) => row[props.idField],
    groupById: (id: TreeTableId) => props.groups?.find((g) => g.id === id),
    mountVue: createMountVue(instance?.appContext ?? null, mounted),
};

/* ---------- The parts ---------- */

const { focusAddRow, renderAddCell } = useAddRow(ctx);
const { focusMoreRow, renderMoreCell } = useMoreRow(ctx);
const { detailsRef, detailsStyle, detailsGroup, closeDetails, repositionAfterRender, GroupDetailsTrigger } =
    useGroupDetails(ctx);
const { groupHeader, unmountRemovedHeaders, unmountAllHeaders } = useGroupHeader(ctx, GroupDetailsTrigger);
const { buildColumns, pruneDetached, unmountAllCells } = useCells(ctx, { renderAddCell, renderMoreCell });
const { decorateRow, refreshRowState, applyMovedHighlight, bindDnd, unbindDnd } = useRows(ctx);
const { selectedCount, applySelection, onSelectionChanged } = useSelection(ctx);
const { onDataSorted, setSort, initialSort } = useSort(ctx);
const { watchColumnDrag, stopColumnDrag } = useColumnDrag(ctx);
const { onGroupVisibilityChanged } = useSync(ctx, {
    buildColumns,
    applySelection,
    applyMovedHighlight,
    refreshRowState,
    focusAddRow,
    focusMoreRow,
    unmountRemovedHeaders,
});

const scrolled = ref(false);
/* After scrolling, let go of the slot content of rows that scrolled away (once per frame) */
let pruneFrame = 0;
function schedulePrune() {
    if (pruneFrame) return;
    pruneFrame = requestAnimationFrame(() => {
        pruneFrame = 0;
        pruneDetached();
    });
}

function onHolderScroll() {
    schedulePrune();
    scrolled.value = (state.holderEl?.scrollLeft ?? 0) > 0;
    /* Open menus (group actions, dropdowns) are pinned to the page, so close them when the table moves under them */
    document.dispatchEvent(new CustomEvent("close-all-dropdowns"));
}

/* ---------- Table lifecycle ---------- */

function create() {
    if (!host.value) return;
    const table = new Tabulator(host.value, {
        data: tableData(ctx),
        index: props.idField,
        columns: buildColumns(),
        layout: "fitColumns",
        height: props.height ?? false,
        placeholder: props.emptyText,
        movableColumns: props.movableColumns,
        resizableColumnFit: true,
        selectableRows: props.selectable ? "highlight" : false,
        selectableRowsCheck: (row: RowComponent) => !isPhantom(row.getData()),
        rowHeader: props.selectable
            ? {
                  formatter: "rowSelection",
                  titleFormatter: "rowSelection",
                  headerSort: false,
                  resizable: false,
                  frozen: true,
                  width: props.draggableRows ? 52 : 40,
                  minWidth: props.draggableRows ? 52 : 40,
                  hozAlign: "center",
                  headerHozAlign: "center",
              }
            : undefined,
        rowFormatter: (row: RowComponent) => decorateRow(row),
        ...(props.groupField
            ? {
                  groupBy: props.groupField,
                  groupValues: props.groups ? [props.groups.map((g) => g.id)] : undefined,
                  /* A group can start closed on its own with `open: false` */
                  groupStartOpen: ((value: TreeTableId) => ctx.groupById(value)?.open ?? props.groupStartOpen) as any,
                  groupToggleElement: "header" as const,
                  /* Tabulator accepts a DOM element here even though its types say string */
                  groupHeader: ((value: any, count: number, _data: any, group: GroupComponent) =>
                      groupHeader(value, count, group)) as any,
              }
            : {}),
        dataTree: true,
        dataTreeChildField: props.childrenField,
        dataTreeElementColumn: treeKey.value,
        dataTreeStartExpanded: props.startExpanded,
        dataTreeChildIndent: props.indent,
        dataTreeBranchElement: '<span class="fu-treetable__branch"></span>',
        dataTreeSelectPropagate: props.propagateSelection,
        dataTreeExpandElement: chevron(false),
        dataTreeCollapseElement: chevron(true),
        headerSortElement: '<span class="fu-treetable__sort"></span>',
        ...initialSort(),
    });
    state.table = table;

    table.on("tableBuilt", () => {
        state.built = true;
        state.holderEl = host.value?.querySelector<HTMLElement>(".tabulator-tableholder") ?? null;
        /* The library's thin scrollbar for the table's own scrolling (sideways, and up and down with a fixed height) */
        state.holderEl?.classList.add("customScrollBar");
        state.holderEl?.addEventListener("scroll", onHolderScroll, { passive: true });
        applySelection();
    });
    table.on("renderComplete", () => {
        pruneDetached();
        focusAddRow();
        focusMoreRow();
        repositionAfterRender();
    });
    table.on("groupVisibilityChanged", onGroupVisibilityChanged);
    table.on("dataSorted", () => nextTick(() => refreshGuides(ctx)));
    table.on("rowClick", (e: UIEvent, row: RowComponent) => {
        if (isPhantom(row.getData())) return;
        const target = e.target as HTMLElement;
        // Controls inside a cell (dropdowns, date pickers, anything marked data-no-row-click) do their own thing
        if (
            target.closest(
                ".fu-treetable__chevron, .fu-treetable__grip, input[type=checkbox], button, a, input, select, textarea, label, [role=button], [role=combobox], [role=listbox], .fu-status-dropdown, .fu-date-picker, .fu-popover-wrap, [data-no-row-click]",
            )
        )
            return;
        emit("row-click", row.getData());
    });
    table.on("rowSelectionChanged", onSelectionChanged);
    watchColumnDrag();
    table.on("columnMoved", (_col, cols) => {
        emit(
            "columns-reordered",
            cols.map((c) => c.getField()).filter((f): f is string => !!f),
        );
    });
    table.on("columnResized", (col) => {
        const key = col.getField();
        if (key) emit("column-resized", { key, width: col.getWidth() });
    });
    table.on("dataSorted", onDataSorted as any);
    table.on("dataTreeRowExpanded", (row) => emit("row-expanded", row.getData()));
    table.on("dataTreeRowCollapsed", (row) => emit("row-collapsed", row.getData()));
}

onMounted(() => {
    create();
    bindDnd();
});

onBeforeUnmount(() => {
    if (pruneFrame) cancelAnimationFrame(pruneFrame);
    stopColumnDrag();
    unbindDnd();
    state.holderEl?.removeEventListener("scroll", onHolderScroll);
    unmountAllCells();
    unmountAllHeaders();
    state.table?.destroy();
    state.table = null;
    state.built = false;
});

watch(
    () => props.selectedIds,
    () => applySelection(),
    { deep: true },
);

watch(
    () => props.height,
    (h) => state.table?.setHeight(h ?? ("" as any)),
);

watch(
    () => props.loading,
    async (v) => {
        if (v) return;
        await nextTick();
        state.table?.redraw(true);
    },
);

/* Whole-table loading placeholder (the `loading` prop) */
const skeletonGrid = computed(() => {
    const lead = props.selectable ? (props.draggableRows ? 52 : 40) : 0;
    const cols = visibleColumns.value.map((c) => (c.width ? `${c.width}px` : "minmax(0, 1fr)"));
    return [lead ? `${lead}px` : "", ...cols].filter(Boolean).join(" ");
});

/* ---------- Public API ---------- */

defineExpose({
    /** Sets the sort as if the person clicked the header (emits `sort-change`). Pass no key to clear it. */
    setSort,
    expandAll() {
        const t = state.table;
        t && walk(t.getRows(), (r) => r.getTreeChildren().length && r.treeExpand());
    },
    collapseAll() {
        const t = state.table;
        t && walk(t.getRows(), (r) => r.getTreeChildren().length && r.treeCollapse());
    },
    clearSelection() {
        emit("update:selectedIds", []);
    },
    redraw(force = true) {
        state.table?.redraw(force);
    },
    getTable: () => state.table,
});
</script>

<template>
    <div class="fu-treetable" :class="[`fu-treetable--group-${groupStyle}`, `fu-treetable--avatar-${groupAvatarShape}`, { 'fu-treetable--fill': typeof height === 'string' && height.trim().endsWith('%'), 'fu-treetable--group-color-editable': groupColorEditable, 'fu-treetable--row-color': showRowColor && !!rowColor, 'is-loading': loading, 'has-selection': selectedCount > 0, 'is-scrolled': scrolled, 'is-sticky-header': stickyHeader }]" :style="stickyHeader ? { '--fu-tt-sticky-top': stickyOffset + 'px' } : undefined">
        <div v-show="!loading" ref="host" class="fu-treetable__host" />
        <!-- Group details card (#group-details): pinned to the page above sticky headers, anchored to the group's title -->
        <Teleport to="body">
            <div
                v-if="detailsGroup && $slots['group-details']"
                ref="detailsRef"
                class="fu-treetable__details"
                role="dialog"
                :aria-label="`${detailsGroup.label} details`"
                tabindex="-1"
                :style="{ ...detailsStyle, width: groupDetailsWidth }"
            >
                <slot name="group-details" :group="detailsGroup" :close="() => closeDetails()" />
            </div>
        </Teleport>
        <!-- Whatever you put in the footer slot sits under the last row, at the bottom left (for example an "Add folder" button) -->
        <div v-if="$slots.footer && !loading" class="fu-treetable__footer">
            <slot name="footer" />
        </div>
        <div v-if="loading" class="fu-treetable__skeleton" aria-busy="true" aria-live="polite">
            <div class="fu-treetable__skeleton-row fu-treetable__skeleton-row--head" :style="{ gridTemplateColumns: skeletonGrid }">
                <div v-if="selectable" class="fu-treetable__skeleton-cell fu-treetable__skeleton-cell--checkbox" />
                <div v-for="col in visibleColumns" :key="col.key">
                    <div class="fu-treetable__skeleton-cell fu-treetable__skeleton-cell--header" />
                </div>
            </div>
            <div
                v-for="i in skeletonRows"
                :key="i"
                class="fu-treetable__skeleton-row"
                :style="{ gridTemplateColumns: skeletonGrid }"
            >
                <div v-if="selectable" class="fu-treetable__skeleton-cell fu-treetable__skeleton-cell--checkbox" />
                <div v-for="(col, ci) in visibleColumns" :key="col.key">
                    <div class="fu-treetable__skeleton-cell" :style="{ width: skeletonWidth(i, ci) }" />
                </div>
            </div>
        </div>
    </div>
</template>
