<script setup lang="ts">
/**
 * FusionDetailsList
 * Label and value pairs, like the Details panel next to a task. Values can be text, a link,
 * or anything you put in a slot.
 */
import type { Component } from "vue";

export interface DetailItem {
    /** Used for the slot name `value-<key>`. */
    key: string;
    label: string;
    value?: string | number | null;
    icon?: Component;
    href?: string;
    /** Leave this row out (for example money for team members). */
    hidden?: boolean;
    /** Show muted text when there is no value. */
    emptyText?: string;
}

withDefaults(
    defineProps<{
        items: DetailItem[];
        title?: string;
        /** stacked: label above value. inline: label left, value right. */
        layout?: "inline" | "stacked";
        divided?: boolean;
        /** A bordered white card. */
        card?: boolean;
        /** Width of the label column in inline layout. */
        labelWidth?: string;
        loading?: boolean;
    }>(),
    { layout: "inline", divided: false, card: true, labelWidth: "40%", loading: false },
);
</script>

<template>
    <section class="fu-details" :class="[`fu-details--${layout}`, { 'is-card': card, 'is-divided': divided }]">
        <header v-if="title || $slots.actions" class="fu-details__head">
            <h3 v-if="title" class="fu-details__title">{{ title }}</h3>
            <div class="fu-details__actions"><slot name="actions" /></div>
        </header>

        <dl class="fu-details__list" :style="{ '--fu-dl-label': labelWidth }">
            <template v-if="loading">
                <div v-for="n in 5" :key="n" class="fu-details__row">
                    <dt><span class="fu-details__skeleton" /></dt>
                    <dd><span class="fu-details__skeleton fu-details__skeleton--wide" /></dd>
                </div>
            </template>
            <template v-else>
                <div v-for="i in items.filter((x) => !x.hidden)" :key="i.key" class="fu-details__row">
                    <dt>
                        <component :is="i.icon" v-if="i.icon" :size="14" class="fu-details__icon" />
                        {{ i.label }}
                    </dt>
                    <dd>
                        <slot :name="`value-${i.key}`" :item="i">
                            <a v-if="i.href && i.value" :href="i.href">{{ i.value }}</a>
                            <template v-else-if="i.value !== undefined && i.value !== null && i.value !== ''">{{
                                i.value
                            }}</template>
                            <span v-else class="fu-details__empty">{{ i.emptyText || "None" }}</span>
                        </slot>
                    </dd>
                </div>
            </template>
        </dl>
    </section>
</template>

