/* Placeholder widths: the same widths and shimmer as FusionListView */
const widthSets = [
    ["55%", "70%", "40%", "65%", "50%"],
    ["75%", "45%", "80%", "55%", "60%"],
    ["60%", "80%", "50%", "70%", "45%"],
    ["45%", "65%", "75%", "40%", "70%"],
    ["70%", "50%", "60%", "80%", "55%"],
];

/** Width of a placeholder bar; `rowIndex` starts at 1. */
export function skeletonWidth(rowIndex: number, colIndex: number): string {
    return widthSets[(rowIndex - 1) % widthSets.length][colIndex % 5];
}
