/**
 * Selection: controlled by `selectedIds` (v-model). The table only reports what the person ticks; when it
 * changes the selection itself (syncing, swapping data) nothing is reported.
 */
import { ref, type Ref } from "vue";
import type { RowComponent } from "tabulator-tables";
import type { TreeTableContext } from "./context";
import { isPhantom } from "./data";
import { walk } from "./tree";

export function useSelection(ctx: TreeTableContext) {
    const selectedCount: Ref<number> = ref(0);

    /** Ticks exactly the rows in `selectedIds`. */
    function applySelection() {
        const table = ctx.state.table;
        if (!table || !ctx.state.built) return;
        const wanted = new Set(ctx.props.selectedIds);
        const current = table.getSelectedData().map(ctx.idOf);
        selectedCount.value = current.length;
        /* Already in sync (the usual case right after the person ticks a box): do nothing */
        if (current.length === wanted.size && current.every((k) => wanted.has(k))) return;

        ctx.state.syncingSelection = true;
        try {
            table.deselectRow();
            /* table.selectRow(keys) only finds top-level rows, so resolve nested rows by walking the tree */
            const found: RowComponent[] = [];
            walk(table.getRows(), (r) => {
                if (wanted.has(ctx.idOf(r.getData()))) found.push(r);
            });
            if (found.length) table.selectRow(found as any);
            selectedCount.value = table.getSelectedData().length;
        } finally {
            ctx.state.syncingSelection = false;
        }
    }

    /** Tabulator's rowSelectionChanged. */
    function onSelectionChanged(data: any[], rows: RowComponent[]) {
        /* Select all ticks the groups' added rows too: untick them, they aren't tasks */
        const added = (rows ?? []).filter((r) => isPhantom(r.getData()));
        if (added.length) {
            ctx.state.table?.deselectRow(added as any);
            return;
        }
        const tasks = data.filter((d) => !isPhantom(d));
        selectedCount.value = tasks.length;
        if (ctx.state.syncingSelection) return;
        ctx.emit("update:selectedIds", tasks.map(ctx.idOf));
    }

    return { selectedCount, applySelection, onSelectionChanged };
}
