/**
 * Sort. Tabulator reports its sort after every data load too; only a change of sort (a header click, or
 * setSort()) is reported, so a page that fetches on `sort-change` and then sets rows doesn't loop.
 * The `sort` prop shows a sort without reporting it back.
 */
import { watch } from "vue";
import type { TreeTableContext } from "./context";
import type { TreeTableSort } from "./types";

function sameSort(a: TreeTableSort | null, b: TreeTableSort | null) {
    return (!a && !b) || (!!a && !!b && a.key === b.key && a.dir === b.dir);
}

export function useSort(ctx: TreeTableContext) {
    let lastSort: TreeTableSort | null = ctx.props.sort ?? null;
    let syncing = false;

    /** Tabulator's dataSorted. */
    function onDataSorted(sorters: { field: string; dir: string }[]) {
        const s = sorters[0];
        const now: TreeTableSort | null = s ? { key: s.field, dir: s.dir as "asc" | "desc" } : null;
        if (sameSort(now, lastSort)) return;
        lastSort = now;
        if (syncing) return;
        ctx.emit("sort-change", now);
    }

    /* The parent changed `sort`: show it without reporting it back */
    watch(
        () => ctx.props.sort,
        (next) => {
            const table = ctx.state.table;
            if (!table || !ctx.state.built || next === undefined) return;
            if (sameSort(next ?? null, lastSort)) return;
            syncing = true;
            try {
                if (next) table.setSort(next.key, next.dir);
                else table.clearSort();
            } finally {
                syncing = false;
            }
        },
        { deep: true },
    );

    /** Sets the sort as if the person clicked the header (emits `sort-change`). Pass no key to clear it. */
    function setSort(key?: string | null, dir: "asc" | "desc" = "asc") {
        const table = ctx.state.table;
        if (!table) return;
        if (key) table.setSort(key, dir);
        else table.clearSort();
    }

    /** Tabulator's initialSort from the `sort` prop. */
    function initialSort() {
        const s = ctx.props.sort;
        return s ? { initialSort: [{ column: s.key, dir: s.dir }] } : {};
    }

    return { onDataSorted, setSort, initialSort };
}
