<script setup lang="ts">
/**
 * FusionDonut
 * Parts of a whole as a ring, with a number in the middle and a legend.
 */
import { computed, ref } from "vue";

export interface DonutSegment {
    label: string;
    value: number;
    /** Any CSS colour. Defaults to the next colour in the palette. */
    color?: string;
}

const PALETTE = [
    "var(--fu-brand-primary-base, #2a0808)",
    "#3a8be0",
    "var(--fu-color-success, #6c9a2e)",
    "var(--fu-color-warning, #f0a135)",
    "var(--fu-color-danger, #c2417a)",
    "var(--fu-color-surface-gray-5, #9aa0a6)",
];

const props = withDefaults(
    defineProps<{
        segments: DonutSegment[];
        /** Diameter in px. */
        size?: number;
        /** Ring thickness in px. */
        thickness?: number;
        centerValue?: string | number;
        centerLabel?: string;
        legend?: "right" | "bottom" | "none";
        /** Show each value as a percentage in the legend. */
        showPercent?: boolean;
        formatValue?: (n: number) => string;
        emptyText?: string;
    }>(),
    { size: 160, thickness: 18, legend: "right", showPercent: false, emptyText: "No data" },
);

const emit = defineEmits<{ (e: "hover", segment: DonutSegment | null): void }>();

const hovered = ref<number | null>(null);
const total = computed(() => props.segments.reduce((a, s) => a + Math.max(0, s.value), 0));
const radius = computed(() => (props.size - props.thickness) / 2);
const circumference = computed(() => 2 * Math.PI * radius.value);
const GAP = 2;

const arcs = computed(() => {
    let offset = 0;
    return props.segments.map((s, i) => {
        const share = total.value > 0 ? Math.max(0, s.value) / total.value : 0;
        const len = Math.max(0, share * circumference.value - (props.segments.length > 1 && share > 0 ? GAP : 0));
        const arc = {
            ...s,
            color: s.color ?? PALETTE[i % PALETTE.length],
            share,
            dash: `${len} ${circumference.value - len}`,
            offset: -offset,
        };
        offset += share * circumference.value;
        return arc;
    });
});

const fmt = (n: number) => (props.formatValue ? props.formatValue(n) : String(n));
const pct = (share: number) => `${Math.round(share * 100)}%`;

function hover(i: number | null) {
    hovered.value = i;
    emit("hover", i === null ? null : props.segments[i]);
}
</script>

<template>
    <figure class="fu-donut" :class="`fu-donut--${legend}`">
        <div class="fu-donut__ring" :style="{ width: `${size}px`, height: `${size}px` }">
            <svg :width="size" :height="size" :viewBox="`0 0 ${size} ${size}`" role="img" :aria-label="`Chart, total ${fmt(total)}`">
                <circle
                    class="fu-donut__track"
                    :cx="size / 2"
                    :cy="size / 2"
                    :r="radius"
                    fill="none"
                    :stroke-width="thickness"
                />
                <g v-if="total > 0" :transform="`rotate(-90 ${size / 2} ${size / 2})`">
                    <circle
                        v-for="(a, i) in arcs"
                        :key="a.label"
                        class="fu-donut__arc"
                        :class="{ 'is-dim': hovered !== null && hovered !== i }"
                        :cx="size / 2"
                        :cy="size / 2"
                        :r="radius"
                        fill="none"
                        :stroke="a.color"
                        :stroke-width="hovered === i ? thickness + 3 : thickness"
                        :stroke-dasharray="a.dash"
                        :stroke-dashoffset="a.offset"
                        @mouseenter="hover(i)"
                        @mouseleave="hover(null)"
                    >
                        <title>{{ a.label }}: {{ fmt(a.value) }} ({{ pct(a.share) }})</title>
                    </circle>
                </g>
            </svg>
            <div class="fu-donut__center">
                <template v-if="total > 0">
                    <slot name="center" :total="total">
                        <b class="fu-donut__value">{{ centerValue ?? fmt(total) }}</b>
                        <span v-if="centerLabel" class="fu-donut__caption">{{ centerLabel }}</span>
                    </slot>
                </template>
                <span v-else class="fu-donut__caption">{{ emptyText }}</span>
            </div>
        </div>

        <figcaption v-if="legend !== 'none' && total > 0" class="fu-donut__legend">
            <div
                v-for="(a, i) in arcs"
                :key="a.label"
                class="fu-donut__item"
                :class="{ 'is-active': hovered === i }"
                @mouseenter="hover(i)"
                @mouseleave="hover(null)"
            >
                <span class="fu-donut__dot" :style="{ background: a.color }" />
                <span class="fu-donut__name">{{ a.label }}</span>
                <b class="fu-donut__num">{{ showPercent ? pct(a.share) : fmt(a.value) }}</b>
            </div>
        </figcaption>
    </figure>
</template>

