<template>
  <div
    class="fu-pill-select"
    :class="[`fu-pill-select--${size}`, `fu-pill-select--${variant}`, { 'fu-pill-select--nowrap': !wrap }]"
    role="radiogroup"
    :aria-label="ariaLabel"
    :style="typeformStyle"
    @keydown="onKeydown"
  >
    <button
      v-for="(opt, i) in options"
      :key="opt.value"
      :ref="(el) => (itemRefs[i] = el as HTMLElement | null)"
      type="button"
      class="fu-pill"
      :class="{
        'is-selected': modelValue === opt.value,
        'is-readonly': readonly,
      }"
      :disabled="disabled || opt.disabled"
      :title="opt.disabled ? opt.disabledReason : undefined"
      role="radio"
      :aria-checked="modelValue === opt.value"
      :tabindex="isTabStop(i) ? 0 : -1"
      @click="select(opt.value)"
    >
      <img
        v-if="typeof opt.icon === 'string'"
        :src="opt.icon"
        class="fu-pill__icon-img"
        alt=""
      />
      <component v-else-if="opt.icon" :is="opt.icon" :size="size === 'xs' ? 14 : 16" class="fu-pill__icon" />
      <span>{{ opt.label }}</span>
    </button>
  </div>
</template>

<script setup lang="ts">
import { computed, ref } from "vue";

type Size = "xs" | "sm" | "md" | "lg";

interface Option {
  value: string | number;
  label: string;
  /** A Lucide icon component, OR an image URL string — both are supported. */
  icon?: any;
  /** This pill cannot be chosen (the rest still can). */
  disabled?: boolean;
  /** Shown as a tooltip on a disabled pill. */
  disabledReason?: string;
}

interface Props {
  modelValue?: string | number | null;
  options: Option[];
  /** xs 24px (default) · sm 36px · md 44px · lg 52px */
  size?: Size;
  disabled?: boolean;
  readonly?: boolean;
  /** outline: a thin border, the chosen pill keeps it. filled: the chosen pill is solid dark. */
  variant?: "outline" | "filled";
  /** Let the pills wrap onto more lines. Turn off for one scrolling line. */
  wrap?: boolean;
  /** Name of the group for screen readers. */
  ariaLabel?: string;

  /* Same naming/behavior as FusionTextInput/FusionRadio's typeform styling —
     drives the selected pill's fill color and the group's font. */
  font?: string;
  fontSize?: string;
  color?: string;
}

const props = withDefaults(defineProps<Props>(), {
  modelValue: null,
  size: "xs",
  disabled: false,
  readonly: false,
  variant: "outline",
  wrap: true,
  ariaLabel: undefined,
  font: undefined,
  fontSize: undefined,
  color: undefined,
});

const emit = defineEmits<{
  (e: "update:modelValue", value: string | number): void;
}>();

function select(value: string | number) {
  if (props.disabled || props.readonly) return;
  emit("update:modelValue", value);
}

/* Arrow keys move between pills, like a native radio group */
const itemRefs = ref<(HTMLElement | null)[]>([]);
const enabled = (i: number) => !props.disabled && !props.options[i]?.disabled;
const selectedIndex = computed(() => props.options.findIndex((o) => o.value === props.modelValue));
function isTabStop(i: number) {
  const first = props.options.findIndex((_, idx) => enabled(idx));
  return selectedIndex.value > -1 && enabled(selectedIndex.value) ? i === selectedIndex.value : i === first;
}
function onKeydown(e: KeyboardEvent) {
  const keys = ["ArrowRight", "ArrowDown", "ArrowLeft", "ArrowUp"];
  if (!keys.includes(e.key) || props.readonly) return;
  const dir = e.key === "ArrowRight" || e.key === "ArrowDown" ? 1 : -1;
  const from = itemRefs.value.findIndex((el) => el === document.activeElement);
  const n = props.options.length;
  for (let step = 1; step <= n; step++) {
    const j = (((from === -1 ? 0 : from) + dir * step) % n + n) % n;
    if (enabled(j)) {
      e.preventDefault();
      itemRefs.value[j]?.focus();
      select(props.options[j].value);
      return;
    }
  }
}

const typeformStyle = computed(() => ({
  ...(props.font ? { "--fu-typeform-font": props.font } : {}),
  ...(props.fontSize ? { "--fu-typeform-font-size": props.fontSize } : {}),
  ...(props.color ? { "--fu-typeform-color": props.color } : {}),
}));
</script>

<style scoped lang="scss">
.fu-pill-select {
  display: flex;
  flex-wrap: wrap;
  gap: rem-calc(12);
  font-family: var(--fu-typeform-font, inherit);
  font-size: var(--fu-typeform-font-size, inherit);
}

.fu-pill {
  display: inline-flex;
  align-items: center;
  gap: rem-calc(8);
  border-radius: rem-calc(999);
  border: rem-calc(1) solid var(--fu-border);
  background: transparent;
  color: var(--fu-color-text);
  font-family: inherit;
  font-size: inherit;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
  white-space: nowrap;

  &:hover:not(:disabled):not(.is-selected) {
    border-color: var(--fu-color-text-light, #9ca3af);
  }

  &:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }

  &.is-readonly {
    cursor: default;
  }

  &.is-selected {
    background: var(--fu-form-control);
    border-color: var(--fu-typeform-color);
  }
}

/* Sizes — xs (default) is a compact 24px pill for forms and toolbars; md matches the ~44px
   pill from the onboarding flow */
.fu-pill-select--xs {
  gap: rem-calc(6);
}
.fu-pill-select--xs .fu-pill {
  height: rem-calc(24);
  padding: 0 rem-calc(10);
  gap: rem-calc(4);
  font-size: rem-calc(12);
}
.fu-pill-select--xs .fu-pill__icon-img {
  width: rem-calc(14);
  height: rem-calc(14);
}
.fu-pill-select--sm .fu-pill {
  height: rem-calc(36);
  padding: 0 rem-calc(16);
  font-size: rem-calc(13);
}
.fu-pill-select--md .fu-pill {
  height: rem-calc(44);
  padding: 0 rem-calc(20);
  font-size: rem-calc(15);
}
.fu-pill-select--lg .fu-pill {
  height: rem-calc(52);
  padding: 0 rem-calc(24);
  font-size: rem-calc(17);
}

.fu-pill-select--nowrap {
  flex-wrap: nowrap;
  overflow-x: auto;
}

.fu-pill:focus-visible {
  outline: rem-calc(2) solid var(--fu-color-text);
  outline-offset: rem-calc(2);
}

/* Filled: the chosen pill is solid dark, the rest keep a clear grey outline */
.fu-pill-select--filled {
  gap: rem-calc(8);

  .fu-pill {
    border: rem-calc(2) solid var(--fu-color-border, #d4d4d4);
    background: var(--fu-surface-white, #ffffff);

    &:hover:not(:disabled):not(.is-selected) {
      border-color: var(--fu-color-text-muted, #9ca3af);
    }

    &.is-selected {
      background: var(--fu-typeform-color, var(--fu-brand-primary-base, #2a0808));
      border-color: var(--fu-typeform-color, var(--fu-brand-primary-base, #2a0808));
      color: #ffffff;
    }
  }
}

.fu-pill__icon-img {
  width: rem-calc(16);
  height: rem-calc(16);
  object-fit: contain;
  flex-shrink: 0;
}
</style>
