/**
 * What the table hands to Tabulator: a copy of the parent's rows (as a tree when they're flat), plus the
 * rows the table adds to each group. Those added rows aren't data:
 *   skeleton: placeholder rows while a group loads (group.loading) or loads more (group.loadingMore)
 *   more:     the "Show more" row (group.more)
 *   add:      the "Enter task title" row (groupAddRow)
 * None of them can be selected, dragged, dropped on, sorted or counted, and cell slots never see them.
 * They stay last in their group, in this order.
 */
import type { RowComponent } from "tabulator-tables";
import type { TreeTableContext } from "./context";
import type { TreeTableGroup, TreeTableId } from "./types";

export type PhantomKind = "skeleton" | "more" | "add";
const PHANTOM = "__fuPhantom";
const PHANTOM_RANK: Record<PhantomKind, number> = { skeleton: 1, more: 2, add: 3 };

export const phantomOf = (data: Record<string, any> | undefined | null): PhantomKind | undefined => data?.[PHANTOM];
export const isPhantom = (data: Record<string, any> | undefined | null) => !!phantomOf(data);
export const isAddRow = (data: Record<string, any> | undefined | null) => phantomOf(data) === "add";

/** Index of a placeholder row in its group (from its id), for its bar widths. */
export function phantomIndex(ctx: TreeTableContext, data: Record<string, any>): number {
    return Number(String(ctx.idOf(data)).split("__").pop()) || 0;
}

/** Flat rows (id + parent id) become a tree. Sibling order follows the order of the array. */
function toTree(ctx: TreeTableContext, rows: Record<string, any>[]): Record<string, any>[] {
    const pk = ctx.props.parentField as string;
    const kids = ctx.props.childrenField;
    const nodes = new Map<TreeTableId, Record<string, any>>();
    rows.forEach((r) => nodes.set(ctx.idOf(r), { ...r }));
    const roots: Record<string, any>[] = [];
    nodes.forEach((node) => {
        const pid = node[pk];
        const parent = pid == null ? undefined : nodes.get(pid);
        if (parent && parent !== node) {
            (parent[kids] ||= []).push(node);
        } else {
            roots.push(node);
        }
    });
    return roots;
}

/** Tabulator mutates its data, so hand it a copy and keep the parent's rows untouched. */
function cloneRows(ctx: TreeTableContext, rows: Record<string, any>[]): Record<string, any>[] {
    const field = ctx.props.childrenField;
    return rows.map((r) => {
        const copy: Record<string, any> = { ...r };
        const kids = r[field];
        if (Array.isArray(kids)) copy[field] = cloneRows(ctx, kids);
        return copy;
    });
}

/** How many rows the next "Show more" loads. */
export function nextMoreCount(ctx: TreeTableContext, g: TreeTableGroup): number {
    if (!g.more) return 0;
    return Math.max(0, Math.min(ctx.props.groupMoreSize, g.more.total - g.more.shown));
}

/** The rows the table adds to one group, in order. */
function phantomsFor(ctx: TreeTableContext, id: TreeTableId): { kind: PhantomKind; n: number }[] {
    const g = ctx.groupById(id);
    const out: { kind: PhantomKind; n: number }[] = [];
    if (g?.loading) {
        const n = g.skeletonRows ?? ctx.props.skeletonRows;
        for (let i = 0; i < n; i++) out.push({ kind: "skeleton", n: i });
    } else if (g?.loadingMore && g.more) {
        const n = Math.max(1, nextMoreCount(ctx, g));
        for (let i = 0; i < n; i++) out.push({ kind: "skeleton", n: i });
    } else if (g?.more && g.more.shown < g.more.total) {
        out.push({ kind: "more", n: 0 });
    }
    if (ctx.props.groupAddRow && !g?.loading) out.push({ kind: "add", n: 0 });
    return out;
}

function groupIds(ctx: TreeTableContext, rows: Record<string, any>[]): TreeTableId[] {
    const gf = ctx.props.groupField as string;
    return ctx.props.groups?.length
        ? ctx.props.groups.map((g) => g.id)
        : [...new Set(rows.map((r) => r[gf]).filter((v) => v != null))];
}

/** The rows handed to Tabulator: the parent's rows, plus each group's added rows. */
export function tableData(ctx: TreeTableContext): Record<string, any>[] {
    const source = ctx.props.parentField ? toTree(ctx, ctx.props.rows) : ctx.props.rows;
    const rows = cloneRows(ctx, source);
    const gf = ctx.props.groupField;
    if (!gf) return rows;
    const added = groupIds(ctx, rows).flatMap((id) =>
        phantomsFor(ctx, id).map(({ kind, n }) => ({
            [ctx.props.idField]: `__fu_${kind}__${id}__${n}`,
            [gf]: id,
            [PHANTOM]: kind,
        })),
    );
    return added.length ? [...rows, ...added] : rows;
}

/** What the added rows look like now; when it changes, the table's data is swapped. */
export function phantomSignatureOf(ctx: TreeTableContext): string {
    if (!ctx.props.groupField) return "";
    return (
        JSON.stringify(
            (ctx.props.groups ?? []).map((g) => [
                g.id,
                phantomsFor(ctx, g.id)
                    .map((p) => p.kind)
                    .join(","),
                g.more?.shown,
                g.more?.total,
            ]),
        ) + String(ctx.props.groupAddRow)
    );
}

/**
 * Sorting keeps each group's added rows last (placeholders, then "Show more", then the title row),
 * whichever way the column is sorted. With sortMode "remote" the rows keep the order they were given.
 */
export function createSorter(ctx: TreeTableContext) {
    return (a: any, b: any, aRow: RowComponent, bRow: RowComponent, _col: any, dir: string) => {
        const aKind = phantomOf(aRow.getData());
        const bKind = phantomOf(bRow.getData());
        if (aKind || bKind) {
            const ra = aKind ? PHANTOM_RANK[aKind] : 0;
            const rb = bKind ? PHANTOM_RANK[bKind] : 0;
            if (ra === rb) return 0;
            const later = dir === "desc" ? -1 : 1;
            return ra > rb ? later : -later;
        }
        if (ctx.props.sortMode === "remote") return 0;
        const empty = (v: unknown) => v === null || v === undefined || v === "";
        if (empty(a) && empty(b)) return 0;
        if (empty(a)) return 1;
        if (empty(b)) return -1;
        if (typeof a === "number" && typeof b === "number") return a - b;
        return String(a).localeCompare(String(b), undefined, { numeric: true, sensitivity: "base" });
    };
}
