<template>
  <FuPopover :align="align" side="bottom" :width="width" :maxHeight="maxHeight">
    <template #trigger>
      <FusionButton :size="size" :text="buttonText" :icon="icon" :variant="variant" :aria-label="ariaLabel || text" />
    </template>

    <div class="fu-checkbox-dropdown__menu" role="group" :aria-label="ariaLabel || text">
      <span v-if="title" class="fu-checkbox-dropdown__title">{{ title }}</span>
      <div v-for="opt in options" :key="String(opt.value)" class="fu-checkbox-dropdown__item">
        <FusionCheckbox
          :id="`${uid}-${opt.value}`"
          size="sm"
          :label="opt.label"
          :disabled="opt.disabled"
          :modelValue="isOn(opt.value)"
          @update:modelValue="(on: boolean) => toggle(opt.value, on)"
        />
        <span v-if="opt.description" class="fu-checkbox-dropdown__desc">{{ opt.description }}</span>
      </div>
    </div>
  </FuPopover>
</template>

<script setup lang="ts">
/**
 * A button that opens a list of checkboxes: for view options, columns or filters that can be on
 * together. v-model is the list of values that are on.
 */
import { computed } from "vue";
import type { Component } from "vue";
import FuPopover from "../popover/FuPopover.vue";
import type { FuPopoverAlign } from "../popover/FuPopover.vue";
import FusionButton from "../button/FusionButton.vue";
import FusionCheckbox from "../checkbox/FusionCheckbox.vue";

export interface CheckboxDropdownOption {
  value: string | number;
  label: string;
  /** A short line under the label */
  description?: string;
  disabled?: boolean;
}

const props = withDefaults(
  defineProps<{
    options: CheckboxDropdownOption[];
    /** The values that are on */
    modelValue?: (string | number)[];
    /** The button's text */
    text?: string;
    icon?: Component | null;
    /** Show how many are on, as "View · 3" */
    showCount?: boolean;
    /** A small heading inside the menu */
    title?: string;
    size?: "sm" | "md";
    variant?: "solid" | "subtle" | "outline" | "ghost";
    align?: FuPopoverAlign;
    width?: string;
    maxHeight?: string;
    ariaLabel?: string;
  }>(),
  {
    modelValue: () => [],
    text: "Options",
    icon: null,
    showCount: true,
    title: "",
    size: "sm",
    variant: "ghost",
    align: "left",
    width: "240px",
    maxHeight: "360px",
    ariaLabel: "",
  },
);

const emit = defineEmits<{ (e: "update:modelValue", value: (string | number)[]): void }>();

const uid = `fu-cbd-${Math.random().toString(36).slice(2, 8)}`;
const isOn = (value: string | number) => props.modelValue.includes(value);
const buttonText = computed(() => (props.showCount && props.modelValue.length ? `${props.text} · ${props.modelValue.length}` : props.text));

function toggle(value: string | number, on: boolean) {
  const rest = props.modelValue.filter((v) => v !== value);
  // Keep the options' order, so the list emitted is stable
  const next = on ? props.options.map((o) => o.value).filter((v) => v === value || rest.includes(v)) : rest;
  emit("update:modelValue", next);
}
</script>

