/**
 * The "Show more" row at the end of a lazy group (group.more). It's a real button: a click or Enter emits
 * `group-load-more`, and the focus comes back to it once the next rows are in, so Enter keeps loading.
 */
import { defineComponent, h, onBeforeUnmount, onMounted, ref } from "vue";
import type { TreeTableContext } from "./context";
import { nextMoreCount } from "./data";
import type { TreeTableId } from "./types";

export function useMoreRow(ctx: TreeTableContext) {
    /* The group whose "Show more" had the focus, so the focus comes back once its next rows are in */
    const moreFocus = ref<TreeTableId | null>(null);

    const MoreRowButton = defineComponent({
        props: {
            groupId: { type: [String, Number], required: true },
        },
        setup(p) {
            return () => {
                const g = ctx.groupById(p.groupId);
                if (!g?.more) return null;
                const n = nextMoreCount(ctx, g);
                const label = ctx.props.groupMoreLabel.replace("{n}", n.toLocaleString());
                return h(
                    "button",
                    {
                        type: "button",
                        class: "fu-treetable__more-btn",
                        "data-group-id": String(p.groupId),
                        onClick: () => {
                            const now = ctx.groupById(p.groupId);
                            /* Already loading: ignore a second click */
                            if (!now || now.loadingMore) return;
                            moreFocus.value = p.groupId;
                            ctx.emit("group-load-more", { groupId: p.groupId });
                        },
                    },
                    [
                        h("span", { class: "fu-treetable__more-label" }, label),
                        h(
                            "span",
                            { class: "fu-treetable__more-count" },
                            `${g.more.shown.toLocaleString()} of ${g.more.total.toLocaleString()} shown`,
                        ),
                    ],
                );
            };
        },
    });

    /** Puts the focus back on the group's "Show more" after its rows arrive (if it's still there). */
    function focusMoreRow() {
        if (moreFocus.value === null || !ctx.host.value) return;
        const id = String(moreFocus.value);
        const btn = [...ctx.host.value.querySelectorAll<HTMLButtonElement>(".fu-treetable__more-btn")].find(
            (el) => el.dataset.groupId === id,
        );
        if (btn) {
            if (document.activeElement !== btn) btn.focus({ preventScroll: true });
            return;
        }
        /* Still loading: keep waiting. Everything shown: let it go */
        if (!ctx.groupById(moreFocus.value)?.loadingMore) moreFocus.value = null;
    }

    function onLeave(e: Event) {
        if (moreFocus.value === null) return;
        if ((e.target as HTMLElement | null)?.closest?.(".fu-treetable__more-btn")) return;
        moreFocus.value = null;
    }
    onMounted(() => {
        document.addEventListener("pointerdown", onLeave, true);
        document.addEventListener("focusin", onLeave, true);
    });
    onBeforeUnmount(() => {
        document.removeEventListener("pointerdown", onLeave, true);
        document.removeEventListener("focusin", onLeave, true);
    });

    /** Draws the button into the "Show more" row's cell, and gives it the focus back after a redraw. */
    function renderMoreCell(wrap: HTMLElement, groupId: TreeTableId, onRendered: (fn: () => void) => void) {
        ctx.mountVue(wrap, h(MoreRowButton, { groupId }));
        onRendered(() => {
            if (moreFocus.value === groupId) wrap.querySelector<HTMLButtonElement>("button")?.focus({ preventScroll: true });
        });
    }

    return { focusMoreRow, renderMoreCell };
}
