<script setup lang="ts">
/**
 * FusionTimePanel
 * The time tracker that drops from the top bar. One column: a timer card on top, then what you are
 * working on (budget, then task), a note, and quick lists of recent, pinned and scheduled items.
 */
import { computed, ref } from "vue";
import { ChevronDown, ChevronLeft, ChevronRight, Pause, Play, Pin, X } from "@lucide/vue";
import FusionTreePicker, { type TreePickerNode } from "../treePicker/FusionTreePicker.vue";
import FusionSwitch from "../switch/FusionSwitch.vue";
import FuSegmentedControl from "../segmented/FuSegmentedControl.vue";

export interface TimeShortcut {
    id: string | number;
    title: string;
    subtitle?: string;
    /** Two letters in the coloured tile. */
    initials?: string;
    /** Tile colour, any CSS colour. */
    color?: string;
}

const props = withDefaults(
    defineProps<{
        /** Day shown in the header, for example "Nov 14". */
        dateLabel: string;
        /** Running or entered time, for example "00:42:17". */
        elapsed?: string;
        running?: boolean;
        /** Clients with their budgets underneath. Only budgets (leaves) can be picked. */
        budgetNodes: TreePickerNode[];
        budgetId?: string | number | null;
        /** Tasks of the chosen budget, as a tree. */
        taskNodes?: TreePickerNode[];
        taskId?: string | number | null;
        pinned?: TimeShortcut[];
        scheduled?: TimeShortcut[];
        recent?: TimeShortcut[];
        note?: string;
        billable?: boolean;
        /** Text under the Billable switch. */
        billableText?: string;
        /** Shown in the timer card when nothing is chosen. */
        emptyTitle?: string;
        emptyText?: string;
        /** For example "5h 12m". Shown in the footer with the week total. */
        todayTotal?: string;
        weekTotal?: string;
        timesheetLabel?: string;
    }>(),
    {
        elapsed: "00:00:00",
        running: false,
        budgetId: null,
        taskNodes: () => [],
        taskId: null,
        pinned: () => [],
        scheduled: () => [],
        recent: () => [],
        note: "",
        billable: true,
        billableText: "",
        emptyTitle: "What are you working on?",
        emptyText: "Pick a budget to start tracking time.",
        todayTotal: "",
        weekTotal: "",
        timesheetLabel: "Open timesheet",
    },
);

const emit = defineEmits<{
    (e: "update:budgetId", id: string | number): void;
    (e: "update:taskId", id: string | number): void;
    (e: "update:note", value: string): void;
    (e: "update:billable", value: boolean): void;
    (e: "start"): void;
    (e: "stop"): void;
    (e: "prev-day"): void;
    (e: "next-day"): void;
    (e: "today"): void;
    (e: "pick", id: string | number): void;
    (e: "timesheet"): void;
    (e: "close"): void;
}>();

const open = ref<"budget" | "task" | null>(null);
const tab = ref("recent");

function findNode(list: TreePickerNode[], id: string | number | null): { node: TreePickerNode; parent?: TreePickerNode } | null {
    if (id === null) return null;
    for (const n of list) {
        if (n.id === id) return { node: n };
        const hit = n.children ? findNode(n.children, id) : null;
        if (hit) return { node: hit.node, parent: hit.parent ?? n };
    }
    return null;
}

const chosen = computed(() => findNode(props.budgetNodes, props.budgetId));
const chosenTask = computed(() => findNode(props.taskNodes, props.taskId)?.node ?? null);

/* Only budgets (rows with no children) can be picked. Clients open and close. */
const budgetTree = computed<TreePickerNode[]>(() => {
    const mark = (n: TreePickerNode): TreePickerNode => ({
        ...n,
        disabled: !!n.children?.length,
        children: n.children?.map(mark),
    });
    return props.budgetNodes.map(mark);
});

function chooseBudget(id: string | number) {
    emit("update:budgetId", id);
    open.value = null;
}

function chooseTask(id: string | number) {
    emit("update:taskId", id);
    open.value = null;
}

const tabs = computed(() => [
    { value: "recent", label: `Recent ${props.recent.length}` },
    { value: "pinned", label: `Pinned ${props.pinned.length}` },
    { value: "scheduled", label: `Scheduled ${props.scheduled.length}` },
]);

const list = computed(() => (tab.value === "pinned" ? props.pinned : tab.value === "scheduled" ? props.scheduled : props.recent));
const emptyLine = computed(() =>
    tab.value === "pinned" ? "Pin a budget to keep it here." : tab.value === "scheduled" ? "Nothing scheduled for this day." : "Nothing tracked recently.",
);

const canStart = computed(() => !!chosen.value && (!props.taskNodes.length || !!chosenTask.value));
</script>

<template>
    <div class="fu-timepanel" role="dialog" aria-label="Time tracker">
        <header class="fu-timepanel__head">
            <h2>Time</h2>
            <div class="fu-timepanel__day">
                <button type="button" aria-label="Previous day" @click="emit('prev-day')"><ChevronLeft :size="16" /></button>
                <button type="button" class="fu-timepanel__daylabel" @click="emit('today')">{{ dateLabel }}</button>
                <button type="button" aria-label="Next day" @click="emit('next-day')"><ChevronRight :size="16" /></button>
            </div>
            <button type="button" class="fu-timepanel__close" aria-label="Close" @click="emit('close')"><X :size="18" /></button>
        </header>

        <!-- Timer card -->
        <section class="fu-timepanel__timer" :class="{ 'is-running': running, 'is-idle': !chosen }">
            <div class="fu-timepanel__clock" aria-live="off">{{ elapsed }}</div>
            <div class="fu-timepanel__now">
                <template v-if="chosen">
                    <b>{{ chosenTask?.label || chosen.node.label }}</b>
                    <span>{{ chosenTask ? chosen.node.label : chosen.parent?.label }}</span>
                </template>
                <template v-else>
                    <b>{{ emptyTitle }}</b>
                    <span>{{ emptyText }}</span>
                </template>
            </div>
            <button
                v-if="!running"
                type="button"
                class="fu-timepanel__go"
                :disabled="!canStart"
                aria-label="Start timer"
                @click="emit('start')"
            >
                <Play :size="22" fill="currentColor" />
            </button>
            <button v-else type="button" class="fu-timepanel__go is-stop" aria-label="Stop and save" @click="emit('stop')">
                <Pause :size="22" fill="currentColor" />
            </button>
        </section>

        <!-- What you are working on -->
        <section class="fu-timepanel__steps">
            <div class="fu-timepanel__step">
                <label>1 · Budget</label>
                <button
                    type="button"
                    class="fu-timepanel__field"
                    :class="{ 'is-empty': !chosen, 'is-open': open === 'budget' }"
                    aria-haspopup="tree"
                    :aria-expanded="open === 'budget'"
                    @click="open = open === 'budget' ? null : 'budget'"
                >
                    <span>{{ chosen ? chosen.node.label : "Choose a budget" }}</span>
                    <small v-if="chosen?.parent">{{ chosen.parent.label }}</small>
                    <ChevronDown :size="14" />
                </button>
                <div v-if="open === 'budget'" class="fu-timepanel__pop">
                    <FusionTreePicker
                        variant="panel"
                        :nodes="budgetTree"
                        :model-value="budgetId"
                        :start-expanded="false"
                        searchable
                        footer
                        search-placeholder="Search clients and budgets"
                        max-height="15rem"
                        @update:model-value="chooseBudget"
                    />
                </div>
            </div>

            <div class="fu-timepanel__step" :class="{ 'is-locked': !chosen }">
                <label>2 · Task</label>
                <button
                    type="button"
                    class="fu-timepanel__field"
                    :class="{ 'is-empty': !chosenTask, 'is-open': open === 'task' }"
                    :disabled="!chosen"
                    aria-haspopup="tree"
                    :aria-expanded="open === 'task'"
                    @click="open = open === 'task' ? null : 'task'"
                >
                    <span>{{ chosenTask ? chosenTask.label : chosen ? "Choose a task" : "Pick a budget first" }}</span>
                    <ChevronDown :size="14" />
                </button>
                <div v-if="open === 'task'" class="fu-timepanel__pop">
                    <FusionTreePicker
                        variant="panel"
                        :nodes="taskNodes"
                        :model-value="taskId"
                        searchable
                        footer
                        max-height="14rem"
                        @update:model-value="chooseTask"
                    />
                </div>
            </div>

            <input
                v-if="chosen"
                class="fu-timepanel__note"
                type="text"
                placeholder="Add a note (optional)"
                :value="note"
                @input="emit('update:note', ($event.target as HTMLInputElement).value)"
            />

            <div v-if="chosen" class="fu-timepanel__bill">
                <div>
                    <b>Billable</b>
                    <span v-if="billableText">{{ billableText }}</span>
                </div>
                <FusionSwitch :model-value="billable" size="sm" @update:model-value="emit('update:billable', $event)" />
            </div>

            <slot name="entry-footer" />
        </section>

        <!-- Quick lists -->
        <section class="fu-timepanel__quick">
            <FuSegmentedControl v-model="tab" :options="tabs" size="sm" block aria-label="Quick lists" />
            <ul class="fu-timepanel__items customScrollBar">
                <li v-for="it in list" :key="it.id" :class="{ 'is-current': it.id === budgetId }">
                    <span class="fu-timepanel__tile" :style="{ background: it.color }">{{ it.initials }}</span>
                    <span class="fu-timepanel__text">
                        <b>{{ it.title }}</b>
                        <span>{{ it.subtitle }}</span>
                    </span>
                    <button type="button" :aria-label="`Track ${it.title}`" @click="emit('pick', it.id)">
                        <Play :size="14" fill="currentColor" />
                    </button>
                </li>
                <li v-if="!list.length" class="fu-timepanel__none">
                    <Pin v-if="tab === 'pinned'" :size="14" />
                    {{ emptyLine }}
                </li>
            </ul>
        </section>

        <footer v-if="todayTotal || weekTotal || timesheetLabel" class="fu-timepanel__foot">
            <span v-if="todayTotal">Today <b>{{ todayTotal }}</b></span>
            <span v-if="weekTotal">Week <b>{{ weekTotal }}</b></span>
            <button type="button" @click="emit('timesheet')">{{ timesheetLabel }} →</button>
        </footer>
    </div>
</template>

